const state = $node["Extract Incident Features"].json ?? {};
const feature = state.feature ?? {};
const prediction = $node["Call AI Model"].json ?? {};
const ti = $node["Lookup Threat Intelligence"].json ?? {};
const asset = $node["Load Asset Context"].json ?? {};
const risk = $node["Evaluate Risk"].json ?? {};
const ingress = $node["Verify Signed Ingress"].json ?? {};
const complete = Boolean(ingress.verified === true && feature.incident && prediction.model_version && ti.policy_revision && asset.context_revision && risk.policy_revision);
const reviewRequired = !complete || feature.quality_status !== 'COMPLETE' || prediction.automation_eligible !== true || prediction.review_required !== false || ti.status === 'UNKNOWN' || ti.status === 'MALICIOUS' || asset.status === 'UNKNOWN' || asset.review_required === true || risk.review_required === true;
return [{ json: { route: reviewRequired ? 'review' : 'shadow', incident_id: feature.incident?.incident_id ?? `UNAVAILABLE-${ingress.source_event_id ?? 'EVENT'}`, source_event_id: ingress.source_event_id ?? 'unavailable', feature_schema_version: feature.feature_schema_version ?? null, feature_quality: feature.quality_status ?? 'PARTIAL', evidence_quality: feature.evidence_quality ?? 0, prediction: complete ? prediction : null, ti_context: complete ? ti : null, asset_context: complete ? asset : null, risk: risk.policy_revision ? risk : null, automation_state: 'SHADOW', selected_playbook: 'persist_incident_queue_review', strong_action_allowed: false, review_required: reviewRequired, rationale: reviewRequired ? ['A safety or completeness gate requires analyst review.', 'No strong response action was executed.'] : ['All required context and model gates passed.', 'SHADOW guard prohibits strong actions.'], audit: { workflow_revision: 'week2-shadow-v2', outcome: 'PERSIST_PENDING' } } }];

const persisted = $json ?? {};
const failed = !persisted.incident_id || !persisted.disposition;
return [{ json: failed ? { response_code: 503, status: 'persistence_failed', review_required: true, automation_state: 'SHADOW', strong_action_allowed: false, message: 'Decision could not be persisted; workflow is fail-closed.' } : { response_code: 200, status: persisted.route === 'review' ? 'review_queued' : 'shadow_queued', review_required: persisted.review_required, automation_state: 'SHADOW', strong_action_allowed: false, incident_id: persisted.incident_id, source_event_id: persisted.source_event_id, disposition: persisted.disposition, notification_status: persisted.notification_status, recorded_at: persisted.recorded_at } }];
